@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun DailyListScreen(
    onSettings: () -> Unit = {},
    viewModel: DailyListViewModel = viewModel(),
) {
    val profiles by viewModel.activeProfiles.collectAsState()
    val medications by viewModel.activeMedications.collectAsState()

    var selectedProfileId by remember { mutableStateOf<Int?>(null) }
    LaunchedEffect(profiles) {
        if (selectedProfileId == null || profiles.none { it.id == selectedProfileId }) {
            selectedProfileId = profiles.firstOrNull()?.id
        }
    }

    val dosesFlow = remember(selectedProfileId) {
        selectedProfileId?.let { viewModel.observeRecentDoses(it) } ?: flowOf(emptyList())
    }
    val doses by dosesFlow.collectAsState(initial = emptyList())

    var showAddDoseSheet by remember { mutableStateOf(false) }
    var pendingConfirmation by remember { mutableStateOf<PendingDoseConfirmation?>(null) }
    var showAbout by remember { mutableStateOf(false) }

    Scaffold(
        topBar = {
            CenterAlignedTopAppBar(
                title = { Text(stringResource(R.string.app_title_bar)) },
                navigationIcon = {
                    IconButton(onClick = { showAbout = true }) {
                        Icon(Icons.Default.Info, contentDescription = stringResource(R.string.about))
                    }
                },
                actions = {
                    IconButton(onClick = onSettings) {
                        Icon(Icons.Default.Settings, contentDescription = stringResource(R.string.settings_label))
                    }
                },
            )
        },
        floatingActionButton = {
            FloatingActionButton(onClick = { showAddDoseSheet = true }) {
                Icon(Icons.Default.Add, contentDescription = stringResource(R.string.log_a_dose))
            }
        },
    ) { padding ->
        if (profiles.isEmpty()) {
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(padding),
                contentAlignment = Alignment.Center,
            ) {
                Text(stringResource(R.string.add_profile_empty_state))
            }
        } else {
            Column(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(padding),
            ) {
                Row(
                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                    modifier = Modifier
                        .fillMaxWidth()
                        .horizontalScroll(rememberScrollState())
                        .padding(16.dp),
                ) {
                    profiles.forEach { profile ->
                        ProfileChip(
                            profile = profile,
                            selected = profile.id == selectedProfileId,
                            onClick = { selectedProfileId = profile.id },
                        )
                    }
                }
                LazyColumn(
                    modifier = Modifier.fillMaxSize(),
                    contentPadding = PaddingValues(horizontal = 16.dp, vertical = 8.dp),
                    verticalArrangement = Arrangement.spacedBy(8.dp),
                ) {
                    items(doses) { doseLog ->
                        val medicationName =
                            medications.firstOrNull { it.id == doseLog.medicationId }?.name
                                ?: stringResource(R.string.unknown_medication_fallback)
                        DoseRow(medicationName = medicationName, doseLog = doseLog)
                    }
                }
            }
        }
    }

    if (showAddDoseSheet) {
        AddDoseDialog(
            profiles = profiles,
            medications = medications,
            initialProfileId = selectedProfileId,
            onDismiss = { showAddDoseSheet = false },
            onSubmit = { profileId, medicationId, doseAmount ->
                viewModel.logDose(
                    profileId = profileId,
                    medicationId = medicationId,
                    givenAtEpochMillis = System.currentTimeMillis(),
                    doseAmount = doseAmount,
                    acknowledgeWarning = false,
                ) { outcome ->
                    when (outcome) {
                        is LogDoseOutcome.Logged -> showAddDoseSheet = false
                        is LogDoseOutcome.NeedsConfirmation -> {
                            pendingConfirmation = PendingDoseConfirmation(
                                profileId,
                                medicationId,
                                doseAmount,
                                outcome.minutesRemaining,
                            )
                        }
                    }
                }
            },
        )
    }

    pendingConfirmation?.let { pending ->
        TooSoonWarningDialog(
            minutesRemaining = pending.minutesRemaining,
            onConfirm = {
                pendingConfirmation = null
                showAddDoseSheet = false
                viewModel.logDose(
                    profileId = pending.profileId,
                    medicationId = pending.medicationId,
                    givenAtEpochMillis = System.currentTimeMillis(),
                    doseAmount = pending.doseAmount,
                    acknowledgeWarning = true,
                ) { }
            },
            onDismiss = { pendingConfirmation = null },
        )
    }

    if (showAbout) {
        AboutDialog(onDismiss = { showAbout = false })
    }
}
